    {
      "id": "s1_analogy",
      "kind": "content",
      "eyebrow": "直觉映射",
      "headline": "现实中的树结构",
      "lead": "树是对一对多层级关系的自然抽象。",
      "notes": "用三个最经典的现实类比建立直觉：族谱看血缘、公司看汇报线、文件系统看路径。强调树的核心特征是‘分层’与‘分支’。",
      "blocks": [
        {
          "id": "b1",
          "type": "list",
          "intent": "用家族族谱、公司组织架构、文件系统目录三个现实类比建立树的直觉"
        }
      ]
    },
    {
      "id": "s2_vs_linear",
      "kind": "content",
      "eyebrow": "结构对比",
      "headline": "线性与树形的分野",
      "lead": "数组与链表表达一维顺次，树表达二维分治。",
      "notes": "数组找第 i 个快但插入慢，链表插入快但找第 i 个慢。树在动态数据集里寻找查找、插入、删除的平衡点。树和图的区别：树是无环连通图，任意两点只有一条路。",
      "blocks": [
        {
          "id": "b2",
          "type": "compare",
          "intent": "对比线性结构（数组/链表）与树结构在形态与查找逻辑上的本质区别"
        }
      ]
    },
    {
      "id": "s3_concepts",
      "kind": "content",
      "eyebrow": "核心概念",
      "headline": "根、叶、深度与高度",
      "lead": "深度自顶向下丈量，高度自底向上生长。",
      "notes": "难点锚点：深度是从根往下数（根深度为0），高度是从叶子往上数（叶子高度为0）。空树高度常定义为-1，单节点高度为0。别死记，想象水深和楼高。砍掉根就变成森林。",
      "blocks": [
        {
          "id": "b3",
          "type": "callout",
          "intent": "澄清深度与高度的易混淆点：深度从根往下数，高度从叶子往上数"
        },
        {
          "id": "b4",
          "type": "flow",
          "intent": "拆解根、叶子、分支等核心概念的形象定义"
        }
      ]
    },
    {
      "id": "s4_math",
      "kind": "content",
      "eyebrow": "图论与数学",
      "headline": "树的拓扑性质",
      "lead": "N 个节点的树必有且仅有 N-1 条边。",
      "notes": "严谨定义：连通无环图。N个节点必有N-1条边。反证法：如果边数>=N，必然成环；如果边数<N-1，必然不连通。这是树的充要条件。",
      "blocks": [
        {
          "id": "b5",
          "type": "formula",
          "intent": "推导树的节点数与边数的数学关系 E=V-1"
        },
        {
          "id": "b6",
          "type": "statement",
          "intent": "给出树的图论定义：无环连通图，任意两点间有且仅有一条简单路径"
        }
      ]
    },
    {
      "id": "s5_binary_intro",
      "kind": "section",
      "notes": "过渡页：从一般树聚焦到计算机科学最偏爱的结构——二叉树。多叉树总能通过左孩子右兄弟法转为二叉树。",
      "blocks": [
        {
          "id": "b7",
          "type": "statement",
          "intent": "章节分隔：从一般树进入二叉树"
        }
      ]
    },
    {
      "id": "s6_why_binary",
      "kind": "content",
      "eyebrow": "设计动机",
      "headline": "为什么偏爱二叉？",
      "lead": "二分思想与硬件二进制的天然契合。",
      "notes": "为什么计算机科学偏爱二叉树？因为计算机本身就是0/1二态，二分查找每次砍掉一半，完美契合。多叉树在内存和算法实现上更复杂，二叉是分治的最简模型。",
      "blocks": [
        {
          "id": "b8",
          "type": "list",
          "intent": "解释为什么计算机科学偏爱二叉树：二分思想与硬件二进制的天然契合"
        }
      ]
    },
    {
      "id": "s7_storage",
      "kind": "content",
      "eyebrow": "物理存储",
      "headline": "内存中的树形",
      "lead": "链式存储靠指针维系，数组存储靠下标计算定位。",
      "notes": "左孩子右兄弟是神级表示法，把多叉树转成二叉树。数组存二叉树（如堆）利用了完全二叉树下标规律，内存连续缓存友好，但极度浪费空间在非完全二叉树上。",
      "blocks": [
        {
          "id": "b9",
          "type": "compare",
          "intent": "对比树的物理存储：左孩子右兄弟/双亲表示法，以及二叉树的数组存储与链式存储"
        }
      ]
    },
    {
      "id": "s8_traversal",
      "kind": "content",
      "eyebrow": "遍历逻辑",
      "headline": "四大遍历路径",
      "lead": "遍历是将二维树形降维为一维序列的关键操作。",
      "notes": "用具体二叉树走一遍：前序(根左右)、中序(左根右)、后序(左右根)、层序。重点在于递归的本质：一棵树由根和子树组成，遍历就是规定何时访问根。",
      "blocks": [
        {
          "id": "b10",
          "type": "flow",
          "intent": "具象展示前/中/后/层序遍历的访问路径，以具体二叉树为例"
        }
      ]
    },
    {
      "id": "s9_traversal_use",
      "kind": "content",
      "eyebrow": "工程映射",
      "headline": "遍历的现实回声",
      "lead": "不同的遍历序对应不同的计算依赖。",
      "notes": "前序对应序列化与目录拷贝（先建根目录）；中序对应BST排序输出；后序对应释放内存与计算目录大小（必须先处理子节点）。遍历时间复杂度必为O(N)，因为每个节点必须访问一次。",
      "blocks": [
        {
          "id": "b11",
          "type": "agenda",
          "intent": "列举前/中/后序遍历在真实工程场景中的对应处理逻辑"
        }
      ]
    },
