      "id": "s10_recursion_stack",
      "kind": "content",
      "eyebrow": "工程陷阱",
      "headline": "递归的代价",
      "lead": "系统栈深度有限，极深树将触发栈溢出。",
      "notes": "递归写法简洁但有栈开销风险（Stack Overflow）。生产环境遇到极深树（如退化链表）必须用迭代+显式栈模拟递归，控制内存使用。",
      "blocks": [
        {
          "id": "b12",
          "type": "code",
          "intent": "展示极深树下如何用显式栈（迭代）替代系统栈以避免栈溢出"
        },
        {
          "id": "b13",
          "type": "callout",
          "intent": "揭示递归写法的栈开销风险与 Stack Overflow 隐患"
        }
      ]
    },
    {
      "id": "s11_degenerate",
      "kind": "content",
      "eyebrow": "性能灾难",
      "headline": "退化：从树到链表",
      "lead": "失去平衡的树，分治退化为线性扫描。",
      "notes": "具象锚点：向 BST 插入有序序列 `[1,2,3,4,5]`，树会向右倾斜成单链表，查找 5 需要 5 次比较，复杂度退化为 O(N)。这是引入平衡树的直接动机。",
      "blocks": [
        {
          "id": "b14",
          "type": "flow",
          "intent": "具象锚点：演示插入有序序列导致 BST 退化为单链表的性能灾难过程"
        }
      ]
    },
    {
      "id": "s12_balance_selection",
      "kind": "content",
      "eyebrow": "平衡与选型",
      "headline": "内存与磁盘的平衡术",
      "lead": "红黑树治内存之疾，B 树解磁盘之痛。",
      "notes": "红黑树适合内存（C++ map, Java TreeMap），通过着色规则减少旋转；B/B+树适合磁盘（数据库索引），扇出大树矮，减少IO。哈希表虽O(1)但无法范围查询，这是树不可替代的原因。",
      "blocks": [
        {
          "id": "b15",
          "type": "compare",
          "intent": "对比 BST 退化问题引出的平衡机制：红黑树（内存）与 B/B+ 树（磁盘）的选型动机"
        }
      ]
    },
    {
      "id": "s13_quiz",
      "kind": "quiz",
      "headline": "随堂检验",
      "notes": "检验核心概念：边数与节点数关系、深度与高度定义、遍历结果推断。确保学生没有把深度高度搞混，且理解退化对复杂度的影响。",
      "blocks": [
        {
          "id": "bq",
          "type": "quiz",
          "intent": "考察节点数与边数关系、深度与高度定义、遍历结果推断"
        }
      ]
    },
    {
      "id": "end",
      "kind": "hero",
      "notes": "收尾：树是分治思想的物理载体。从族谱到文件系统，从内存红黑树到磁盘B树，树在层级与效率间寻找平衡。",
      "blocks": [
        {
          "id": "b_end",
          "type": "hero",
          "intent": "收尾：总结树作为层级与分治骨架的核心地位"
        }
      ]
    }
  ]
